import { Clock, Search, X } from 'lucide-react'
import { useEffect, useId, useRef, useState } from 'react'

import { cx } from '~/lib/cx'
import { Label } from './label'
import styles from './search-input.module.scss'

export interface SearchInputProps {
  label?: string
  placeholder?: string
  value?: string
  defaultValue?: string
  onChange?: (value: string) => void
  /** Called on Enter or when a recent search is chosen. */
  onSearch?: (query: string) => void
  /** localStorage key for the recent searches. */
  historyKey?: string
  /** Seed entries used when storage is empty (demos, first run). */
  initialHistory?: string[]
  maxHistory?: number
  className?: string
  id?: string
}

function readHistory(key: string): string[] {
  if (typeof window === 'undefined') return []
  try {
    const raw = window.localStorage.getItem(key)
    const parsed: unknown = raw ? JSON.parse(raw) : []
    return Array.isArray(parsed)
      ? parsed.filter((item): item is string => typeof item === 'string')
      : []
  } catch {
    return []
  }
}

/**
 * Search field with recent-query history. Enter stores the query, focus with an
 * empty value reveals history, and every entry is keyboard reachable.
 */
export function SearchInput({
  label,
  placeholder = 'Search…',
  value: valueProp,
  defaultValue = '',
  onChange,
  onSearch,
  historyKey = 'vz.search-history',
  initialHistory = [],
  maxHistory = 5,
  className,
  id: idProp,
}: SearchInputProps) {
  const generatedId = useId()
  const id = idProp ?? generatedId
  const listId = `${id}-history`
  const [uncontrolled, setUncontrolled] = useState(defaultValue)
  const query = valueProp ?? uncontrolled
  const [history, setHistory] = useState<string[]>(() => {
    const stored = readHistory(historyKey)
    return (stored.length > 0 ? stored : initialHistory).slice(0, maxHistory)
  })
  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)

  const setQuery = (next: string) => {
    if (valueProp === undefined) setUncontrolled(next)
    onChange?.(next)
  }

  const commit = (next: string) => {
    const trimmed = next.trim()
    if (!trimmed) return
    const nextHistory = [
      trimmed,
      ...history.filter((item) => item.toLowerCase() !== trimmed.toLowerCase()),
    ].slice(0, maxHistory)
    setHistory(nextHistory)
    try {
      window.localStorage.setItem(historyKey, JSON.stringify(nextHistory))
    } catch {
      /* storage blocked */
    }
    setOpen(false)
    onSearch?.(trimmed)
  }

  const clearHistory = () => {
    setHistory([])
    try {
      window.localStorage.removeItem(historyKey)
    } catch {
      /* storage blocked */
    }
  }

  useEffect(() => {
    if (!open) return
    const onPointerDown = (event: PointerEvent) => {
      if (rootRef.current?.contains(event.target as Node)) return
      setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  const showHistory = open && query.trim().length === 0 && history.length > 0

  return (
    <div ref={rootRef} className={cx(styles.root, className)}>
      {label ? <Label htmlFor={id}>{label}</Label> : null}
      <div className={styles.shell}>
        <span className={styles.icon}>
          <Search aria-hidden />
        </span>
        <input
          id={id}
          type="search"
          role="combobox"
          aria-expanded={showHistory}
          aria-controls={listId}
          aria-autocomplete="list"
          autoComplete="off"
          value={query}
          placeholder={placeholder}
          className={styles.input}
          onChange={(event) => setQuery(event.currentTarget.value)}
          onFocus={() => setOpen(true)}
          onKeyDown={(event) => {
            if (event.key === 'Escape') setOpen(false)
            if (event.key === 'Enter') {
              event.preventDefault()
              commit(query)
            }
            if (event.key === 'ArrowDown' && showHistory) {
              event.preventDefault()
              rootRef.current
                ?.querySelector<HTMLButtonElement>('[role="option"]')
                ?.focus()
            }
          }}
        />
        {query ? (
          <button
            type="button"
            className={styles.clear}
            aria-label="Clear search"
            onClick={() => {
              setQuery('')
              setOpen(true)
            }}
          >
            <X aria-hidden />
          </button>
        ) : null}
      </div>

      {showHistory ? (
        <div id={listId} role="listbox" aria-label="Recent searches" className={styles.dropdown}>
          <div className={styles.dropdownHead}>
            <span className={styles.dropdownTitle}>Recent searches</span>
            <button type="button" className={styles.clearHistory} onClick={clearHistory}>
              Clear
            </button>
          </div>
          <div className={styles.list}>
            {history.map((item) => (
              <button
                key={item}
                type="button"
                role="option"
                aria-selected="false"
                className={styles.item}
                onClick={() => {
                  setQuery(item)
                  commit(item)
                }}
              >
                <Clock aria-hidden />
                <span className={styles.itemLabel}>{item}</span>
              </button>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
  min-width: 0;
}

.shell {
  display: flex;
  align-items: center;
  gap: vz.space(2);
  height: vz.space(10);
  padding-inline: vz.space(3);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  color: vz.color('foreground');
  transition:
    border-color vz.duration('fast') vz.ease('out'),
    box-shadow vz.duration('fast') vz.ease('out');

  &:focus-within {
    border-color: vz.color('primary');
    box-shadow: 0 0 0 3px vz.color('primary', 0.18);
  }
}

.icon {
  flex: none;
  color: vz.color('muted-foreground');

  svg {
    @include vz.icon(4);
  }
}

.input {
  min-width: 0;
  flex: 1;
  height: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: vz.font-size('sm');
  outline: none;

  @include vz.placeholder {
    color: vz.color('muted-foreground');
  }
}

.clear {
  display: inline-flex;
  width: 1.5rem;
  height: 1.5rem;
  flex: none;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: vz.radius('xs');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;

  @include vz.hover {
    background: vz.color('accent');
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);

  svg {
    @include vz.icon(3);
  }
}

.dropdown {
  position: absolute;
  top: calc(100% + #{vz.space(1.5)});
  right: 0;
  left: 0;
  z-index: vz.z('popover');
  overflow: hidden;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('popover', 0.92);
  color: vz.color('popover-foreground');
  box-shadow: vz.elevation(3);
  backdrop-filter: blur(18px) saturate(180%);
  animation: vz-search-in 160ms vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.dropdown-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(2);
  padding: vz.space(2) vz.space(3);
  border-bottom: 1px solid vz.color('border', 0.7);
}

.dropdown-title {
  color: vz.color('muted-foreground');
  font-size: 0.625rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.clear-history {
  border: 0;
  background: transparent;
  color: vz.color('muted-foreground');
  font-size: 0.6875rem;
  cursor: pointer;

  @include vz.hover {
    color: vz.color('destructive');
  }

  @include vz.focus-ring(2px, 1px, 0.6);
}

.list {
  display: flex;
  flex-direction: column;
  padding: vz.space(1);
}

.item {
  display: flex;
  align-items: center;
  gap: vz.space(2);
  min-height: vz.space(8);
  padding: vz.space(1) vz.space(2);
  border: 0;
  border-radius: vz.radius('sm');
  background: transparent;
  color: inherit;
  font-size: vz.font-size('sm');
  text-align: left;
  cursor: pointer;

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 1px, 0.6);

  svg {
    @include vz.icon(3.5);

    color: vz.color('muted-foreground');
  }
}

.item-label {
  flex: 1;
  min-width: 0;

  @include vz.truncate;
}

@keyframes vz-search-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.99);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
